<script>
(function(){var lastMessage='field-panel_message';document.addEventListener('focusin',function(e){if(e.target&&e.target.tagName==='TEXTAREA')lastMessage=e.target.id;});document.addEventListener('click',function(e){var b=e.target.closest('.ms-var');if(!b)return;var f=document.getElementById(lastMessage)||document.getElementById('field-panel_message');if(!f)return;var s=f.selectionStart||f.value.length,en=f.selectionEnd||f.value.length,v=b.dataset.value;f.value=f.value.substring(0,s)+v+f.value.substring(en);f.focus();f.selectionStart=f.selectionEnd=s+v.length;});})();
</script>
